@@ -0,0 +1,349 @@
+import { Column } from '~/column.ts';
+import { entityKind, is } from '~/entity.ts';
+import type { SelectResultField } from '~/query-builders/select.types.ts';
+import { type SQL, sql, type SQLWrapper } from '~/sql/sql.ts';
+
+export type WindowFrameBoundaryType =
+	| 'unbounded_preceding'
+	| 'preceding'
+	| 'current_row'
+	| 'following'
+	| 'unbounded_following';
+
+export class WindowFrameBoundary implements SQLWrapper {
+	static readonly [entityKind]: string = 'WindowFrameBoundary';
+
+	constructor(
+		readonly type: WindowFrameBoundaryType,
+		readonly offset?: number,
+	) {}
+
+	get rank(): number {
+		switch (this.type) {
+			case 'unbounded_preceding':
+				return -Infinity;
+			case 'preceding':
+				return -(this.offset ?? 0);
+			case 'current_row':
+				return 0;
+			case 'following':
+				return this.offset ?? 0;
+			case 'unbounded_following':
+				return Infinity;
+		}
+	}
+
+	getSQL(): SQL {
+		switch (this.type) {
+			case 'unbounded_preceding':
+				return sql.raw('unbounded preceding');
+			case 'preceding':
+				return sql.raw(`${this.offset} preceding`);
+			case 'current_row':
+				return sql.raw('current row');
+			case 'following':
+				return sql.raw(`${this.offset} following`);
+			case 'unbounded_following':
+				return sql.raw('unbounded following');
+		}
+	}
+}
+
+export const unboundedPreceding = new WindowFrameBoundary('unbounded_preceding');
+export const currentRow = new WindowFrameBoundary('current_row');
+export const unboundedFollowing = new WindowFrameBoundary('unbounded_following');
+
+export function preceding(offset: number): WindowFrameBoundary {
+	if (typeof offset !== 'number' || !Number.isInteger(offset) || offset < 0) {
+		throw new Error(`preceding expects a non-negative integer, received ${offset}`);
+	}
+	return new WindowFrameBoundary('preceding', offset);
+}
+
+export function following(offset: number): WindowFrameBoundary {
+	if (typeof offset !== 'number' || !Number.isInteger(offset) || offset < 0) {
+		throw new Error(`following expects a non-negative integer, received ${offset}`);
+	}
+	return new WindowFrameBoundary('following', offset);
+
